      arg === 'on',
      context.getAppState,
      context.setAppState,
    )",
    "new": "  const arg = args?.trim().toLowerCase()
  if (arg === 'on' || arg === 'off') {
    const { getAppState, setAppState } = context as FastCommandContext
    const result = await handleFastModeShortcut(
      arg === 'on',
      getAppState,
      setAppState,
